        parameters: {
            query?: never;
            header: {
                /** @description The lease generation the decision was made against, or `*` for a store never issued one. Required */
                "If-Match": string;
            };
            path?: never;
            cookie?: never;
        };
        /** @description `tenant_id` and `store_id`; optionally `edge_placement` (`EDGE_PLACEMENT_IN_STORE`, `EDGE_PLACEMENT_HOSTED_BY_OPERATOR` or `EDGE_PLACEMENT_HOSTED_BY_PLATFORM`) when the store is moving, absent for a swap in place (ADR-0110); for a hosted placement, `region_country` and `region_label`, where its data will rest (ADR-0114); and `acknowledge_undrained`, the undrained generation this bump knowingly abandons. No body names a generation: the server issues it */
        requestBody: {
            content: {
                "application/json": components["schemas"]["BumpLeaseRequest"];
            };
        };
        responses: {
            /** @description Issued and published: a different machine is the store now (ADR-0108). The new generation is published as the store's `lease` node, with the receipt floor beside it where the cloud has one (ADR-0149), and the box on the old generation stops installing updates. The body carries `config_version_id`. Audited with the generation issued */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["PublishedConfig"];
                };
            };
            /** @description tenant_id or store_id is not a ULID; edge_placement is not one of the three; the region is incomplete, malformed or given where no hosted placement is named; If-Match is absent or malformed; or a value needs a recorded confirmation first */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description No session */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description The role lacks console.stores.manage */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description The lease moved since you read it: re-read and retry. The error names the current generation */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description Every attempt to publish the lease node lost a race with another publish: try again */
            412: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description The previous machine still holds events this cloud has never seen, naming the generation to acknowledge to proceed, which abandons them; or the store's configuration would not validate with the node */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description The lease store or the configuration store is unreachable */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
        };
