    admin_upload_ota_release: {
        parameters: {
            query: {
                /** @description The release the bytes are, spelled bare as a rollout's `target_version` names it, without a leading `v`. Required */
                release: string;
                /** @description The target triple the executable is built for. Required */
                arch: string;
            };
            header: {
                /** @description minisign's signature over these exact bytes: the second line of the `.minisig` file, as base64. Required */
                "x-pos-minisig": string;
            };
            path?: never;
            cookie?: never;
        };
        /** @description The bare release executable, not the release archive: the edge installs the bytes it is handed, so the signature has to cover these (ADR-0088). `docs/release-runbook.md` step 5 gives the exact request */
        requestBody?: {
            content: {
                "application/octet-stream": unknown;
            };
        };
        responses: {
            /** @description Already hosted with these exact bytes: the release is unchanged, so a re-run of a release step does not fail. The body is as for 201. Audited */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Hosted: the signature, then the executable, are stored, and only then the release is recorded. The body carries `release`, `arch`, `size_bytes` and `sha256`. Audited */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description release or arch is absent or unusable; the body is empty; or the signature header is absent, not base64, or not a minisign signature. An absent query parameter is refused by the framework, without the error envelope */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description No session */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description The role lacks console.ota.publish */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description This release is already hosted for this target with different bytes. A version a ring may have installed does not change */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description The executable is over 128 MiB. Answered by the server's body limit, without the error envelope */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The storage keys could not be composed */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description The object store or the release registry is unreachable: send the same upload again later */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
        };
    };
